mapper.select:
select m.user_id, aw.workspace_id as application_workspace_id, min(v.version_id) as version_id from application_members m join users u on u.user_id = m.user_id and u.status = 'ACTIVE' join applications a on a.app_id = m.app_id and a.enabled = true join application_workspaces aw on aw.app_id = m.app_id and aw.enabled = true join application_workspace_versions v on v.application_workspace_id = aw.workspace_id and v.status = 'ACTIVE' join code_repositories r on r.repository_id = aw.repository_id where m.deleted_at is null and (r.repository_type is null or r.repository_type <> 'AUTOMATION_CODE_REPOSITORY')
and ( m.user_id > #{afterUserId} or (m.user_id = #{afterUserId} and aw.workspace_id > #{afterWorkspaceId}) )
group by m.user_id, aw.workspace_id order by m.user_id, aw.workspace_id limit #{limit}

select lcw.user_id, lcw.workspace_id, lcw.client_instance_id, lcw.root_digest from local_client_workspaces lcw join users u on u.user_id = lcw.user_id and u.status = 'ACTIVE' join workspaces w on w.workspace_id = lcw.workspace_id and w.status = 'ACTIVE' where 1 = 1
and ( lcw.user_id > #{afterUserId} or (lcw.user_id = #{afterUserId} and lcw.workspace_id > #{afterWorkspaceId}) )
order by lcw.user_id, lcw.workspace_id limit #{limit}

select user_id, application_workspace_id as target_id,
       status, reason, message, checked_at
from application_workspace_git_access_checks
where user_id = #{userId}
  and application_workspace_id = #{targetId}

select user_id, workspace_id as target_id,
       status, reason, message, checked_at
from local_workspace_git_access_checks
where user_id = #{userId}
  and workspace_id = #{targetId}

mapper.insert:
merge into application_workspace_git_access_checks(
    user_id, application_workspace_id, status, reason, message,
    checked_at, created_at, updated_at
) key(user_id, application_workspace_id) values (
    #{row.userId}, #{row.targetId}, #{row.status}, #{row.reason}, #{row.message},
    #{row.checkedAt}, #{now}, #{now}
)

merge into local_workspace_git_access_checks(
    user_id, workspace_id, status, reason, message,
    checked_at, created_at, updated_at
) key(user_id, workspace_id) values (
    #{row.userId}, #{row.targetId}, #{row.status}, #{row.reason}, #{row.message},
    #{row.checkedAt}, #{now}, #{now}
)
